export async function receiveOutreachReply(accountId:string,key:string,input:unknown){if(!idOk(accountId)||!/^[A-Za-z0-9_-]{43}$/.test(key))return fail('Reply adapter authentication failed.',401);return storage(s=>{const a=s.outreach?.accounts.find(a=>a.id===accountId&&a.enabled);if(!a||!timingSafeEqual(Buffer.from(a.digest,'hex'),Buffer.from(digestKey(key),'hex')))return fail('Reply adapter authentication failed.',401);const r=inboundInput(input);const receipt=s.outreach!.receipts.find(x=>x.accountId===accountId&&x.eventId===r.eventId);if(!receipt)intakeRate(s,'social-'+accountId,Date.now());return recordOutreachReply(s,accountId,r,{kind:'admin',id:'admin'});},true);}


export async function receiveMetaBatch(batch:ReturnType<typeof parseMetaMessages>){return storage(s=>{
 const w=s.outreach;if(!w)return {recorded:0,duplicates:0,ignored:batch.ignored+batch.messages.length};let recorded=0,duplicates=0,ignored=batch.ignored;
 for(const event of batch.messages){const account=w.accounts.find(a=>a.enabled&&a.channel===event.channel&&a.meta?.businessId===event.businessId);if(!account){ignored++;continue;}
  const current=w.conversations.find(c=>c.accountId===account.id&&c.contactId===event.reply.contactId);
  if(current&&event.reply.receivedAt<current.receivedAt&&!event.reply.optOut){ignored++;continue;}
  const duplicate=w.receipts.some(r=>r.accountId===account.id&&r.eventId===event.reply.eventId);if(!duplicate)intakeRate(s,'social-'+account.id,Date.now());
  const result=recordOutreachReply(s,account.id,event.reply,{kind:'admin',id:'admin'});
  if(result.duplicate){duplicates++;continue;}
  const c=w.conversations.find(c=>c.id===result.id)!;if(event.proof.receivedAt===c.receivedAt)c.provider=event.proof;else delete c.provider;account.meta!.lastVerifiedAt=Date.now();recorded++;
 }return {recorded,duplicates,ignored};
 },true);}
